def is_balanced_parens(text):
    count = 0
    for ch in text:
        if ch == '(':
            count += 1
        elif ch == ')':
            count -= 1
        if count < 0:
            return False
    return count == 0

def is_balanced_brackets(text):
    stack = []
    pairs = {'(': ')', '[': ']', '{': '}'}
    for ch in text:
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in pairs.values():
            if not stack or stack[-1] != ch:
                return False
            stack.pop()
    return len(stack) == 0

