def zip_extend(a, b):
    # Zip two lists, padding the shorter with its own last element.
    if not a and not b:
        return []
    if not a:
        return [(None, x) for x in b]
    if not b:
        return [(x, None) for x in a]
    result = []
    for i in range(max(len(a), len(b))):
        val_a = a[i] if i < len(a) else a[-1]
        val_b = b[i] if i < len(b) else b[-1]
        result.append((val_a, val_b))
    return result

