def normalize_minmax(values, new_min=0.0, new_max=1.0):
    """Scale values to [new_min, new_max] range."""
    if not values:
        return []
    old_min = min(values)
    old_max = max(values)
    if old_min == old_max:
        return [0.5 * (new_min + new_max)] * len(values)
    return [
        new_min + (v - old_min) / (old_max - old_min) * (new_max - new_min)
        for v in values
    ]

def normalize_zscore(values):
    """Z-score normalization: (x - mean) / std."""
    if not values:
        return []
    n = len(values)
    mean = sum(values) / n
    variance = sum((v - mean) ** 2 for v in values) / n
    std = variance ** 0.5
    if std == 0:
        return [0.0] * n
    return [(v - mean) / std for v in values]

